    basis->m[1][0] = t1.y;
    basis->m[2][0] = t1.z;
    basis->m[0][1] = t2.x;
    basis->m[1][1] = t2.y;
    basis->m[2][1] = t2.z;
    basis->m[0][2] = t3.x;
    basis->m[1][2] = t3.y;
    basis->m[2][2] = t3.z;
    return ADCS_OK;
}
adcs_status_t adcs_triad(const adcs_vec3_t *pb, const adcs_vec3_t *sb, const adcs_vec3_t *pi,
