adcs_status_t adcs_pilot_normalized_bdot(const adcs_vec3_t *field_body_t,const adcs_vec3_t *field_rate_t_s,double normalized_gain_nm_s_t,double max_dipole_a_m2,adcs_actuator_command_t *command) {

canonical_solution:
    double b2, p, n;
    adcs_vec3_t parallel, perp;
    if (command == NULL)
        return ADCS_E_NULL;
    command->command = (adcs_vec3_t){0, 0, 0};
    command->saturated_axes = 0;
    if ((field_body_t == NULL) || (field_rate_t_s == NULL))
        return ADCS_E_NULL;
    if ((!isfinite(field_body_t->x)) || (!isfinite(field_body_t->y)) ||
        (!isfinite(field_body_t->z)) || (!isfinite(field_rate_t_s->x)) ||
        (!isfinite(field_rate_t_s->y)) || (!isfinite(field_rate_t_s->z)) ||
        (!isfinite(normalized_gain_nm_s_t)) || (normalized_gain_nm_s_t < 0) ||
        (!isfinite(max_dipole_a_m2)) || (max_dipole_a_m2 < 0))
        return ADCS_E_RANGE;
    b2 = adcs_vec3_dot(field_body_t, field_body_t);
    if (b2 <= ADCS_EPS_NORM * ADCS_EPS_NORM)
