double adcs_vec3_dot(const adcs_vec3_t *a, const adcs_vec3_t *b) {
    return a->x * b->x + a->y * b->y + a->z * b->z;
}
adcs_vec3_t adcs_vec3_cross(const adcs_vec3_t *a, const adcs_vec3_t *b) {
    adcs_vec3_t r = {a->y * b->z - a->z * b->y, a->z * b->x - a->x * b->z,
                     a->x * b->y - a->y * b->x};
    return r;
}
double adcs_vec3_norm(const adcs_vec3_t *v) {
    return sqrt(adcs_vec3_dot(v, v));
}
int adcs_is_finite_vec3(const adcs_vec3_t *v) {
    return (v != NULL) && isfinite(v->x) && isfinite(v->y) && isfinite(v->z);
}
adcs_status_t adcs_vec3_normalize(const adcs_vec3_t *in, double minimum_norm, adcs_vec3_t *out) {
    double n;
    if ((in == NULL) || (out == NULL))
        return ADCS_E_NULL;
    if ((!adcs_is_finite_vec3(in)) || (!isfinite(minimum_norm)) || (minimum_norm < 0.0))
        return ADCS_E_NOT_FINITE;
    n = adcs_vec3_norm(in);
    if (n <= minimum_norm) {
        out->x = 0.0;
        out->y = 0.0;
        out->z = 0.0;
        return ADCS_E_DEGENERATE;
    }
    *out = adcs_vec3_scale(in, 1.0 / n);
    return ADCS_OK;
}
adcs_vec3_t adcs_vec3_add(const adcs_vec3_t *a, const adcs_vec3_t *b) {
    adcs_vec3_t r = {a->x + b->x, a->y + b->y, a->z + b->z};
    return r;
}
adcs_vec3_t adcs_vec3_sub(const adcs_vec3_t *a, const adcs_vec3_t *b) {
    adcs_vec3_t r = {a->x - b->x, a->y - b->y, a->z - b->z};
    return r;
}
adcs_vec3_t adcs_vec3_scale(const adcs_vec3_t *v, double s) {
    adcs_vec3_t r = {s * v->x, s * v->y, s * v->z};
    return r;
}
adcs_vec3_t adcs_mat3_mul_vec(const adcs_mat3_t *a, const adcs_vec3_t *v) {
    adcs_vec3_t r = {a->m[0][0] * v->x + a->m[0][1] * v->y + a->m[0][2] * v->z,
                     a->m[1][0] * v->x + a->m[1][1] * v->y + a->m[1][2] * v->z,
                     a->m[2][0] * v->x + a->m[2][1] * v->y + a->m[2][2] * v->z};
    return r;
}
adcs_mat3_t adcs_mat3_mul(const adcs_mat3_t *a, const adcs_mat3_t *b) {
    adcs_mat3_t r = {{{0}}};
    size_t i, j, k;
    for (i = 0; i < 3; i++)
        for (j = 0; j < 3; j++)
            for (k = 0; k < 3; k++)
                r.m[i][j] += a->m[i][k] * b->m[k][j];
    return r;
}
adcs_mat3_t adcs_mat3_transpose(const adcs_mat3_t *a) {
    adcs_mat3_t r;
    size_t i, j;
    for (i = 0; i < 3; i++)
        for (j = 0; j < 3; j++)
            r.m[i][j] = a->m[j][i];
    return r;
}
double adcs_mat3_det(const adcs_mat3_t *a) {
    return a->m[0][0] * (a->m[1][1] * a->m[2][2] - a->m[1][2] * a->m[2][1]) -
           a->m[0][1] * (a->m[1][0] * a->m[2][2] - a->m[1][2] * a->m[2][0]) +
           a->m[0][2] * (a->m[1][0] * a->m[2][1] - a->m[1][1] * a->m[2][0]);
}
adcs_mat3_t adcs_mat3_identity(void) {
    adcs_mat3_t r = {{{1, 0, 0}, {0, 1, 0}, {0, 0, 1}}};
    return r;
}
adcs_mat3_t adcs_mat3_skew(const adcs_vec3_t *v) {
    adcs_mat3_t r = {{{0, -v->z, v->y}, {v->z, 0, -v->x}, {-v->y, v->x, 0}}};
    return r;
}
adcs_mat3_t adcs_mat3_add(const adcs_mat3_t *a, const adcs_mat3_t *b) {
    adcs_mat3_t r;
    size_t i, j;
    for (i = 0; i < 3; i++)
        for (j = 0; j < 3; j++)
            r.m[i][j] = a->m[i][j] + b->m[i][j];
    return r;
}
adcs_mat3_t adcs_mat3_scale(const adcs_mat3_t *a, double s) {
    adcs_mat3_t r;
    size_t i, j;
    for (i = 0; i < 3; i++)
        for (j = 0; j < 3; j++)
            r.m[i][j] = s * a->m[i][j];
    return r;
}
adcs_mat3_t adcs_mat3_outer(const adcs_vec3_t *a, const adcs_vec3_t *b) {
    adcs_mat3_t r = {{{a->x * b->x, a->x * b->y, a->x * b->z},
                      {a->y * b->x, a->y * b->y, a->y * b->z},
                      {a->z * b->x, a->z * b->y, a->z * b->z}}};
    return r;
}
double adcs_mat3_frobenius_error_identity(const adcs_mat3_t *a) {
    double s = 0.0, d;
    size_t i, j;
    for (i = 0; i < 3; i++)
        for (j = 0; j < 3; j++) {
            d = a->m[i][j] - ((i == j) ? 1.0 : 0.0);
            s += d * d;
        }
    return sqrt(s);
}
adcs_status_t adcs_quat_normalize(const adcs_quat_t *in, adcs_quat_t *out) {
    double n;
    if ((in == NULL) || (out == NULL))
        return ADCS_E_NULL;
    n = sqrt(in->w * in->w + in->x * in->x + in->y * in->y + in->z * in->z);
    if ((!isfinite(n)) || (n <= ADCS_EPS_QUAT)) {
        *out = (adcs_quat_t){1, 0, 0, 0};
        return ADCS_E_DEGENERATE;
    }
    *out = (adcs_quat_t){in->w / n, in->x / n, in->y / n, in->z / n};
    return ADCS_OK;
}
adcs_quat_t adcs_quat_conjugate(const adcs_quat_t *q) {
    adcs_quat_t r = {q->w, -q->x, -q->y, -q->z};
    return r;
}
adcs_quat_t adcs_quat_multiply(const adcs_quat_t *a, const adcs_quat_t *b) {
    adcs_quat_t r = {a->w * b->w - a->x * b->x - a->y * b->y - a->z * b->z,
                     a->w * b->x + a->x * b->w + a->y * b->z - a->z * b->y,
                     a->w * b->y - a->x * b->z + a->y * b->w + a->z * b->x,
                     a->w * b->z + a->x * b->y - a->y * b->x + a->z * b->w};
    return r;
}
adcs_mat3_t adcs_quat_to_dcm_bi(const adcs_quat_t *qin) {
    adcs_quat_t q;
    adcs_mat3_t r;
    (void)adcs_quat_normalize(qin, &q);
    r.m[0][0] = 1 - 2 * (q.y * q.y + q.z * q.z);
    r.m[0][1] = 2 * (q.x * q.y + q.w * q.z);
    r.m[0][2] = 2 * (q.x * q.z - q.w * q.y);
    r.m[1][0] = 2 * (q.x * q.y - q.w * q.z);
    r.m[1][1] = 1 - 2 * (q.x * q.x + q.z * q.z);
    r.m[1][2] = 2 * (q.y * q.z + q.w * q.x);
    r.m[2][0] = 2 * (q.x * q.z + q.w * q.y);
    r.m[2][1] = 2 * (q.y * q.z - q.w * q.x);
    r.m[2][2] = 1 - 2 * (q.x * q.x + q.y * q.y);
    return r;
}
double adcs_quat_abs_dot(const adcs_quat_t *a, const adcs_quat_t *b) {
    return fabs(a->w * b->w + a->x * b->x + a->y * b->y + a->z * b->z);
}
adcs_status_t adcs_quat_propagate_body_rate(const adcs_quat_t *q, const adcs_vec3_t *w, double dt,
                                            adcs_quat_t *out) {
    double angle, half, s;
    adcs_quat_t dq, next;
    if ((q == NULL) || (w == NULL) || (out == NULL))
        return ADCS_E_NULL;
    if ((!adcs_is_finite_vec3(w)) || (!isfinite(dt)) || (dt < 0.0))
        return ADCS_E_RANGE;
    if (adcs_quat_normalize(q, &next) != ADCS_OK)
        return ADCS_E_DEGENERATE;
    angle = adcs_vec3_norm(w) * dt;
    if (angle <= ADCS_EPS_NORM) {
        dq = (adcs_quat_t){1.0, 0.5 * w->x * dt, 0.5 * w->y * dt, 0.5 * w->z * dt};
    } else {
        half = 0.5 * angle;
        s = sin(half) / adcs_vec3_norm(w);
        dq = (adcs_quat_t){cos(half), s * w->x, s * w->y, s * w->z};
    }
    next = adcs_quat_multiply(&dq, &next);
    return adcs_quat_normalize(&next, out);
}

static adcs_status_t triad_basis(const adcs_vec3_t *a, const adcs_vec3_t *b, adcs_mat3_t *basis) {
    adcs_vec3_t t1, t2, t3;
    if (adcs_vec3_normalize(a, ADCS_EPS_NORM, &t1) != ADCS_OK)
        return ADCS_E_DEGENERATE;
    t2 = adcs_vec3_cross(&t1, b);
    if (adcs_vec3_normalize(&t2, ADCS_EPS_COLLINEAR, &t2) != ADCS_OK)
        return ADCS_E_DEGENERATE;
    t3 = adcs_vec3_cross(&t1, &t2);
    basis->m[0][0] = t1.x;
    basis->m[1][0] = t1.y;
    basis->m[2][0] = t1.z;
    basis->m[0][1] = t2.x;
    basis->m[1][1] = t2.y;
    basis->m[2][1] = t2.z;
    basis->m[0][2] = t3.x;
    basis->m[1][2] = t3.y;
    basis->m[2][2] = t3.z;
    return ADCS_OK;
}
adcs_status_t adcs_triad(const adcs_vec3_t *pb, const adcs_vec3_t *sb, const adcs_vec3_t *pi,
                         const adcs_vec3_t *si, adcs_mat3_t *c) {
    adcs_mat3_t b, r, rt;
    if ((pb == NULL) || (sb == NULL) || (pi == NULL) || (si == NULL) || (c == NULL))
        return ADCS_E_NULL;
    if ((triad_basis(pb, sb, &b) != ADCS_OK) || (triad_basis(pi, si, &r) != ADCS_OK)) {
        *c = adcs_mat3_identity();
        return ADCS_E_DEGENERATE;
    }
    rt = adcs_mat3_transpose(&r);
    *c = adcs_mat3_mul(&b, &rt);
    return ADCS_OK;
}

adcs_status_t adcs_quest(const adcs_vec3_t *bv, const adcs_vec3_t *iv, const double *weights,
                         size_t count, adcs_quat_t *out) {
    adcs_mat3_t b = {{{0}}};
    double k[4][4] = {{0}}, v[4] = {1, 0, 0, 0}, next[4], sigma, z[3], nrm, diff, weight_sum = 0.0;
    size_t i, j, n, iter;
    if ((bv == NULL) || (iv == NULL) || (weights == NULL) || (out == NULL))
        return ADCS_E_NULL;
    if (count < 2U)
        return ADCS_E_RANGE;
    for (n = 0; n < count; n++) {
        adcs_vec3_t bn, in;
        adcs_mat3_t o;
        if ((!isfinite(weights[n])) || (weights[n] <= 0.0) ||
            adcs_vec3_normalize(&bv[n], ADCS_EPS_NORM, &bn) != ADCS_OK ||
            adcs_vec3_normalize(&iv[n], ADCS_EPS_NORM, &in) != ADCS_OK)
            return ADCS_E_RANGE;
        weight_sum += weights[n];
        o = adcs_mat3_outer(&bn, &in);
        for (i = 0; i < 3; i++)
            for (j = 0; j < 3; j++)
                b.m[i][j] += weights[n] * o.m[i][j];
    }
    sigma = b.m[0][0] + b.m[1][1] + b.m[2][2];
    z[0] = b.m[1][2] - b.m[2][1];
    z[1] = b.m[2][0] - b.m[0][2];
    z[2] = b.m[0][1] - b.m[1][0];
    k[0][0] = sigma;
    for (i = 0; i < 3; i++) {
        k[0][i + 1] = z[i];
        k[i + 1][0] = z[i];
        for (j = 0; j < 3; j++)
            k[i + 1][j + 1] = b.m[i][j] + b.m[j][i] - ((i == j) ? sigma : 0.0);
    }
    for (i = 0; i < 4; i++)
        k[i][i] += 3.0 * weight_sum;
    for (iter = 0; iter < ADCS_MAX_ITERATIONS; iter++) {
        nrm = 0.0;
        for (i = 0; i < 4; i++) {
            next[i] = 0.0;
            for (j = 0; j < 4; j++)
                next[i] += k[i][j] * v[j];
            nrm += next[i] * next[i];
        }
        nrm = sqrt(nrm);
        if (nrm <= ADCS_EPS_NORM)
            return ADCS_E_DEGENERATE;
        diff = 0.0;
        for (i = 0; i < 4; i++) {
            next[i] /= nrm;
            diff += fabs(next[i] - v[i]);
            v[i] = next[i];
        }
        if (diff < 1.0e-13)
            break;
    }
    *out = (adcs_quat_t){v[0], v[1], v[2], v[3]};
    if (out->w < 0.0) {
        out->w = -out->w;
        out->x = -out->x;
        out->y = -out->y;
        out->z = -out->z;
    }
    return (iter < ADCS_MAX_ITERATIONS) ? ADCS_OK : ADCS_E_NO_CONVERGENCE;
}

adcs_status_t adcs_bdot_update(adcs_bdot_state_t *state, const adcs_vec3_t *field, double time,
                               double alpha, adcs_vec3_t *rate) {
    adcs_vec3_t delta, raw, new_part, old_part;
    double dt;
    if ((state == NULL) || (field == NULL) || (rate == NULL))
        return ADCS_E_NULL;
    if ((!adcs_is_finite_vec3(field)) || (!isfinite(time)) || (!isfinite(alpha)) || (alpha < 0.0) ||
        (alpha > 1.0))
        return ADCS_E_RANGE;
    if (!state->initialized) {
        state->previous_field_t = *field;
        state->previous_time_s = time;
        state->initialized = 1;
        *rate = (adcs_vec3_t){0, 0, 0};
        return ADCS_OK;
    }
    dt = time - state->previous_time_s;
    if ((!isfinite(dt)) || (dt <= 0.0))
        return ADCS_E_RANGE;
    delta = adcs_vec3_sub(field, &state->previous_field_t);
    raw = adcs_vec3_scale(&delta, 1.0 / dt);
    new_part = adcs_vec3_scale(&raw, alpha);
    old_part = adcs_vec3_scale(rate, 1.0 - alpha);
    *rate = adcs_vec3_add(&new_part, &old_part);
    state->previous_field_t = *field;
    state->previous_time_s = time;
    return ADCS_OK;
}
adcs_status_t adcs_bdot_dipole(const adcs_vec3_t *field, const adcs_vec3_t *rate, double gain,
                               double maxdip, adcs_actuator_command_t *cmd) {
    double b2, parallel;
    adcs_vec3_t parallel_part, perp;
    double vals[3];
    size_t i;
    if ((field == NULL) || (rate == NULL) || (cmd == NULL))
        return ADCS_E_NULL;
    if ((!adcs_is_finite_vec3(field)) || (!adcs_is_finite_vec3(rate)) || (!isfinite(gain)) ||
        (!isfinite(maxdip)) || (gain < 0.0) || (maxdip < 0.0))
        return ADCS_E_RANGE;
    b2 = adcs_vec3_dot(field, field);
    if (b2 <= ADCS_EPS_NORM * ADCS_EPS_NORM) {
        cmd->command = (adcs_vec3_t){0, 0, 0};
        cmd->saturated_axes = 0U;
        return ADCS_E_DEGENERATE;
    }
