        return ADCS_E_RANGE;
    if (adcs_vec3_norm(requested_a_m2) <= ADCS_EPS_NORM)
        return ADCS_OK;
    input[0] = requested_a_m2->x / full_scale_a_m2;
    input[1] = requested_a_m2->y / full_scale_a_m2;
