        if (fabs(limited) > 0 && fabs(limited) < minimum_duty) {
            limited = copysign(minimum_duty, limited);
            duty->saturated_axes |= (uint32_t)(1u << i);
        }
        output[i] = limited;
    }
    return ADCS_OK;
}

