adcs_status_t adcs_pilot_vector_pair_separation_mismatch(const adcs_vec3_t *body_a, const adcs_vec3_t *body_b, const adcs_vec3_t *inertial_a, const adcs_vec3_t *inertial_b, double *mismatch_rad) {

canonical_solution:
    double ba, bb, ia, ib, bc, ic;
    if (mismatch_rad == NULL)
        return ADCS_E_NULL;
    *mismatch_rad = INFINITY;
    if ((body_a == NULL) || (body_b == NULL) || (inertial_a == NULL) || (inertial_b == NULL))
        return ADCS_E_NULL;
    if (!adcs_is_finite_vec3(body_a) || !adcs_is_finite_vec3(body_b) ||
        !adcs_is_finite_vec3(inertial_a) || !adcs_is_finite_vec3(inertial_b))
        return ADCS_E_DEGENERATE;
    ba = adcs_vec3_norm(body_a);
    bb = adcs_vec3_norm(body_b);
    ia = adcs_vec3_norm(inertial_a);
    ib = adcs_vec3_norm(inertial_b);
    if ((!isfinite(ba)) || (!isfinite(bb)) || (!isfinite(ia)) || (!isfinite(ib)) ||
        (ba <= ADCS_EPS_NORM) || (bb <= ADCS_EPS_NORM) || (ia <= ADCS_EPS_NORM) ||
        (ib <= ADCS_EPS_NORM))
        return ADCS_E_DEGENERATE;
    bc = adcs_vec3_dot(body_a, body_b) / (ba * bb);
    ic = adcs_vec3_dot(inertial_a, inertial_b) / (ia * ib);
    if (bc > 1.0)
        bc = 1.0;
    if (bc < -1.0)
        bc = -1.0;
    if (ic > 1.0)
        ic = 1.0;
    if (ic < -1.0)
        ic = -1.0;
    *mismatch_rad = fabs(acos(bc) - acos(ic));
    return ADCS_OK;
}

