    z[1] = b.m[2][0] - b.m[0][2];
    z[2] = b.m[0][1] - b.m[1][0];
    k[0][0] = sigma;
    for (i = 0; i < 3; i++) {
        k[0][i + 1] = z[i];
        k[i + 1][0] = z[i];
        for (j = 0; j < 3; j++)
            k[i + 1][j + 1] = b.m[i][j] + b.m[j][i] - ((i == j) ? sigma : 0.0);
    }
    for (i = 0; i < 4; i++)
        k[i][i] += 3.0 * weight_sum;
