        nrm = 0.0;
        for (i = 0; i < 4; i++) {
            next[i] = 0.0;
            for (j = 0; j < 4; j++)
                next[i] += k[i][j] * v[j];
            nrm += next[i] * next[i];
        }
        nrm = sqrt(nrm);
        if (nrm <= ADCS_EPS_NORM)
            return ADCS_E_DEGENERATE;
        diff = 0.0;
        for (i = 0; i < 4; i++) {
            next[i] /= nrm;
            diff += fabs(next[i] - v[i]);
            v[i] = next[i];
        }
        if (diff < 1.0e-13)
            break;
    }
    *out = (adcs_quat_t){v[0], v[1], v[2], v[3]};
