}

adcs_status_t adcs_bdot_update(adcs_bdot_state_t *state, const adcs_vec3_t *field, double time,
                               double alpha, adcs_vec3_t *rate) {
    adcs_vec3_t delta, raw, new_part, old_part;
    double dt;
    if ((state == NULL) || (field == NULL) || (rate == NULL))
        return ADCS_E_NULL;
    if ((!adcs_is_finite_vec3(field)) || (!isfinite(time)) || (!isfinite(alpha)) || (alpha < 0.0) ||
        (alpha > 1.0))
        return ADCS_E_RANGE;
    if (!state->initialized) {
        state->previous_field_t = *field;
        state->previous_time_s = time;
        state->initialized = 1;
        *rate = (adcs_vec3_t){0, 0, 0};
        return ADCS_OK;
    }
    dt = time - state->previous_time_s;
    if ((!isfinite(dt)) || (dt <= 0.0))
        return ADCS_E_RANGE;
    delta = adcs_vec3_sub(field, &state->previous_field_t);
    raw = adcs_vec3_scale(&delta, 1.0 / dt);
    new_part = adcs_vec3_scale(&raw, alpha);
    old_part = adcs_vec3_scale(rate, 1.0 - alpha);
    *rate = adcs_vec3_add(&new_part, &old_part);
    state->previous_field_t = *field;
    state->previous_time_s = time;
    return ADCS_OK;
}
adcs_status_t adcs_bdot_dipole(const adcs_vec3_t *field, const adcs_vec3_t *rate, double gain,
                               double maxdip, adcs_actuator_command_t *cmd) {
    double b2, parallel;
    adcs_vec3_t parallel_part, perp;
    double vals[3];
    size_t i;
    if ((field == NULL) || (rate == NULL) || (cmd == NULL))
        return ADCS_E_NULL;
    if ((!adcs_is_finite_vec3(field)) || (!adcs_is_finite_vec3(rate)) || (!isfinite(gain)) ||
        (!isfinite(maxdip)) || (gain < 0.0) || (maxdip < 0.0))
        return ADCS_E_RANGE;
    b2 = adcs_vec3_dot(field, field);
    if (b2 <= ADCS_EPS_NORM * ADCS_EPS_NORM) {
        cmd->command = (adcs_vec3_t){0, 0, 0};
        cmd->saturated_axes = 0U;
        return ADCS_E_DEGENERATE;
    }
    parallel = adcs_vec3_dot(rate, field) / b2;
    parallel_part = adcs_vec3_scale(field, parallel);
    perp = adcs_vec3_sub(rate, &parallel_part);
    cmd->command = adcs_vec3_scale(&perp, -gain);
    cmd->saturated_axes = 0U;
    vals[0] = cmd->command.x;
    vals[1] = cmd->command.y;
    vals[2] = cmd->command.z;
    for (i = 0; i < 3; i++)
        if (fabs(vals[i]) > maxdip) {
            vals[i] = copysign(maxdip, vals[i]);
            cmd->saturated_axes |= (uint32_t)(1U << i);
        }
    cmd->command = (adcs_vec3_t){vals[0], vals[1], vals[2]};
    return ADCS_OK;
}
adcs_status_t adcs_wheel_momentum(const adcs_wheel_t *wheels, size_t count, adcs_vec3_t *h) {
    size_t i;
    adcs_vec3_t axis, term;
    if ((wheels == NULL) || (h == NULL))
        return ADCS_E_NULL;
    *h = (adcs_vec3_t){0, 0, 0};
    for (i = 0; i < count; i++) {
        if ((!isfinite(wheels[i].inertia_kg_m2)) || (!isfinite(wheels[i].speed_rad_s)) ||
            (wheels[i].inertia_kg_m2 < 0.0) ||
            adcs_vec3_normalize(&wheels[i].axis_body, ADCS_EPS_NORM, &axis) != ADCS_OK)
            return ADCS_E_RANGE;
        term = adcs_vec3_scale(&axis, wheels[i].inertia_kg_m2 * wheels[i].speed_rad_s);
        *h = adcs_vec3_add(h, &term);
    }
    return ADCS_OK;
}
adcs_status_t adcs_momentum_unload_dipole(const adcs_vec3_t *herr, const adcs_vec3_t *field,
                                          double gain, double maxdip, adcs_actuator_command_t *cmd,
                                          adcs_vec3_t *torque) {
    adcs_vec3_t desired, cross;
    double b2, scale, n;
    if ((herr == NULL) || (field == NULL) || (cmd == NULL) || (torque == NULL))
        return ADCS_E_NULL;
    if ((!adcs_is_finite_vec3(herr)) || (!adcs_is_finite_vec3(field)) || (!isfinite(gain)) ||
        (!isfinite(maxdip)) || (gain < 0.0) || (maxdip < 0.0))
        return ADCS_E_RANGE;
    b2 = adcs_vec3_dot(field, field);
    if (b2 <= ADCS_EPS_NORM * ADCS_EPS_NORM) {
        cmd->command = (adcs_vec3_t){0, 0, 0};
        cmd->saturated_axes = 0U;
        *torque = cmd->command;
        return ADCS_E_DEGENERATE;
    }
    desired = adcs_vec3_scale(herr, -gain);
    cross = adcs_vec3_cross(field, &desired);
    cmd->command = adcs_vec3_scale(&cross, 1.0 / b2);
    n = adcs_vec3_norm(&cmd->command);
    cmd->saturated_axes = 0U;
    if (n > maxdip) {
        scale = maxdip / n;
        cmd->command = adcs_vec3_scale(&cmd->command, scale);
        cmd->saturated_axes = 7U;
    }
    *torque = adcs_vec3_cross(&cmd->command, field);
    return ADCS_OK;
}
adcs_status_t adcs_limit_scalar(double v, const adcs_actuator_limit_t *l, double *o) {
    if ((l == NULL) || (o == NULL))
        return ADCS_E_NULL;
    if ((!isfinite(v)) || (l->min_value > l->max_value))
        return ADCS_E_RANGE;
    *o = ADCS_CLAMP(v, l->min_value, l->max_value);
    return ADCS_OK;
}
