            isfinite(rs_config.switch_margin_rad) &&
            (rs_config.switch_margin_rad >= 0.0) &&
            isfinite(rs_config.residual_weight_floor_rad) &&
            (rs_config.residual_weight_floor_rad > 0.0) &&
            isfinite(rs_config.output_alpha) &&
            (rs_config.output_alpha > 0.0) &&
