                        ? (adcs_quat_t){-triad.w, -triad.x, -triad.y, -triad.z}
                        : triad;
    star_weight = 1.0 / (rs_config.residual_weight_floor_rad + rs_input.star_residual_rad);
    triad_weight = 1.0 / (rs_config.residual_weight_floor_rad + rs_input.triad_residual_rad);
    selected = (adcs_quat_t){
        (star_weight * star.w + triad_weight * aligned_triad.w),
        (star_weight * star.x + triad_weight * aligned_triad.x),
        (star_weight * star.y + triad_weight * aligned_triad.y),
        (star_weight * star.z + triad_weight * aligned_triad.z)};
