        rs_state.primary = RS_FAULT;
        rs_output.source = RS_FAULT;
        rs_output.primary = RS_FAULT;
        return;
    }
    rs_output.source = RS_FUSED;
} else {
    selected = (rs_state.primary == RS_STAR) ? star : triad;
    rs_output.source = rs_state.primary;
}
signed_dot = rs_state.previous_q_bi.w * selected.w +
             rs_state.previous_q_bi.x * selected.x +
             rs_state.previous_q_bi.y * selected.y +
             rs_state.previous_q_bi.z * selected.z;
if (signed_dot < 0.0) {
    selected = (adcs_quat_t){-selected.w, -selected.x, -selected.y, -selected.z};
