blend = (adcs_quat_t){
    previous_weight * rs_state.previous_q_bi.w + rs_config.output_alpha * selected.w,
    previous_weight * rs_state.previous_q_bi.x + rs_config.output_alpha * selected.x,
    previous_weight * rs_state.previous_q_bi.y + rs_config.output_alpha * selected.y,
