    return r;
}
double adcs_quat_abs_dot(const adcs_quat_t *a, const adcs_quat_t *b) {
    return fabs(a->w * b->w + a->x * b->x + a->y * b->y + a->z * b->z);
}
adcs_status_t adcs_quat_propagate_body_rate(const adcs_quat_t *q, const adcs_vec3_t *w, double dt,
                                            adcs_quat_t *out) {
    double angle, half, s;
    adcs_quat_t dq, next;
    if ((q == NULL) || (w == NULL) || (out == NULL))
        return ADCS_E_NULL;
    if ((!adcs_is_finite_vec3(w)) || (!isfinite(dt)) || (dt < 0.0))
        return ADCS_E_RANGE;
    if (adcs_quat_normalize(q, &next) != ADCS_OK)
        return ADCS_E_DEGENERATE;
    angle = adcs_vec3_norm(w) * dt;
    if (angle <= ADCS_EPS_NORM) {
        dq = (adcs_quat_t){1.0, 0.5 * w->x * dt, 0.5 * w->y * dt, 0.5 * w->z * dt};
    } else {
        half = 0.5 * angle;
        s = sin(half) / adcs_vec3_norm(w);
        dq = (adcs_quat_t){cos(half), s * w->x, s * w->y, s * w->z};
    }
    next = adcs_quat_multiply(&dq, &next);
    return adcs_quat_normalize(&next, out);
}

static adcs_status_t triad_basis(const adcs_vec3_t *a, const adcs_vec3_t *b, adcs_mat3_t *basis) {
    adcs_vec3_t t1, t2, t3;
    if (adcs_vec3_normalize(a, ADCS_EPS_NORM, &t1) != ADCS_OK)
        return ADCS_E_DEGENERATE;
    t2 = adcs_vec3_cross(&t1, b);
    if (adcs_vec3_normalize(&t2, ADCS_EPS_COLLINEAR, &t2) != ADCS_OK)
        return ADCS_E_DEGENERATE;
    t3 = adcs_vec3_cross(&t1, &t2);
    basis->m[0][0] = t1.x;
    basis->m[1][0] = t1.y;
    basis->m[2][0] = t1.z;
    basis->m[0][1] = t2.x;
    basis->m[1][1] = t2.y;
    basis->m[2][1] = t2.z;
    basis->m[0][2] = t3.x;
    basis->m[1][2] = t3.y;
    basis->m[2][2] = t3.z;
    return ADCS_OK;
}
adcs_status_t adcs_triad(const adcs_vec3_t *pb, const adcs_vec3_t *sb, const adcs_vec3_t *pi,
                         const adcs_vec3_t *si, adcs_mat3_t *c) {
    adcs_mat3_t b, r, rt;
    if ((pb == NULL) || (sb == NULL) || (pi == NULL) || (si == NULL) || (c == NULL))
        return ADCS_E_NULL;
    if ((triad_basis(pb, sb, &b) != ADCS_OK) || (triad_basis(pi, si, &r) != ADCS_OK)) {
        *c = adcs_mat3_identity();
        return ADCS_E_DEGENERATE;
    }
    rt = adcs_mat3_transpose(&r);
    *c = adcs_mat3_mul(&b, &rt);
    return ADCS_OK;
}

adcs_status_t adcs_quest(const adcs_vec3_t *bv, const adcs_vec3_t *iv, const double *weights,
                         size_t count, adcs_quat_t *out) {
    adcs_mat3_t b = {{{0}}};
    double k[4][4] = {{0}}, v[4] = {1, 0, 0, 0}, next[4], sigma, z[3], nrm, diff, weight_sum = 0.0;
    size_t i, j, n, iter;
    if ((bv == NULL) || (iv == NULL) || (weights == NULL) || (out == NULL))
        return ADCS_E_NULL;
    if (count < 2U)
        return ADCS_E_RANGE;
    for (n = 0; n < count; n++) {
        adcs_vec3_t bn, in;
        adcs_mat3_t o;
        if ((!isfinite(weights[n])) || (weights[n] <= 0.0) ||
            adcs_vec3_normalize(&bv[n], ADCS_EPS_NORM, &bn) != ADCS_OK ||
            adcs_vec3_normalize(&iv[n], ADCS_EPS_NORM, &in) != ADCS_OK)
            return ADCS_E_RANGE;
        weight_sum += weights[n];
        o = adcs_mat3_outer(&bn, &in);
        for (i = 0; i < 3; i++)
            for (j = 0; j < 3; j++)
                b.m[i][j] += weights[n] * o.m[i][j];
    }
    sigma = b.m[0][0] + b.m[1][1] + b.m[2][2];
    z[0] = b.m[1][2] - b.m[2][1];
    z[1] = b.m[2][0] - b.m[0][2];
    z[2] = b.m[0][1] - b.m[1][0];
    k[0][0] = sigma;
    for (i = 0; i < 3; i++) {
        k[0][i + 1] = z[i];
        k[i + 1][0] = z[i];
        for (j = 0; j < 3; j++)
            k[i + 1][j + 1] = b.m[i][j] + b.m[j][i] - ((i == j) ? sigma : 0.0);
    }
    for (i = 0; i < 4; i++)
        k[i][i] += 3.0 * weight_sum;
    for (iter = 0; iter < ADCS_MAX_ITERATIONS; iter++) {
        nrm = 0.0;
        for (i = 0; i < 4; i++) {
            next[i] = 0.0;
            for (j = 0; j < 4; j++)
                next[i] += k[i][j] * v[j];
            nrm += next[i] * next[i];
        }
        nrm = sqrt(nrm);
        if (nrm <= ADCS_EPS_NORM)
            return ADCS_E_DEGENERATE;
        diff = 0.0;
        for (i = 0; i < 4; i++) {
            next[i] /= nrm;
            diff += fabs(next[i] - v[i]);
            v[i] = next[i];
        }
        if (diff < 1.0e-13)
            break;
    }
    *out = (adcs_quat_t){v[0], v[1], v[2], v[3]};
    if (out->w < 0.0) {
        out->w = -out->w;
        out->x = -out->x;
        out->y = -out->y;
        out->z = -out->z;
    }
    return (iter < ADCS_MAX_ITERATIONS) ? ADCS_OK : ADCS_E_NO_CONVERGENCE;
}

adcs_status_t adcs_bdot_update(adcs_bdot_state_t *state, const adcs_vec3_t *field, double time,
                               double alpha, adcs_vec3_t *rate) {
    adcs_vec3_t delta, raw, new_part, old_part;
    double dt;
    if ((state == NULL) || (field == NULL) || (rate == NULL))
        return ADCS_E_NULL;
    if ((!adcs_is_finite_vec3(field)) || (!isfinite(time)) || (!isfinite(alpha)) || (alpha < 0.0) ||
        (alpha > 1.0))
        return ADCS_E_RANGE;
    if (!state->initialized) {
        state->previous_field_t = *field;
        state->previous_time_s = time;
        state->initialized = 1;
        *rate = (adcs_vec3_t){0, 0, 0};
        return ADCS_OK;
    }
    dt = time - state->previous_time_s;
    if ((!isfinite(dt)) || (dt <= 0.0))
        return ADCS_E_RANGE;
    delta = adcs_vec3_sub(field, &state->previous_field_t);
    raw = adcs_vec3_scale(&delta, 1.0 / dt);
    new_part = adcs_vec3_scale(&raw, alpha);
    old_part = adcs_vec3_scale(rate, 1.0 - alpha);
    *rate = adcs_vec3_add(&new_part, &old_part);
    state->previous_field_t = *field;
    state->previous_time_s = time;
    return ADCS_OK;
}
adcs_status_t adcs_bdot_dipole(const adcs_vec3_t *field, const adcs_vec3_t *rate, double gain,
                               double maxdip, adcs_actuator_command_t *cmd) {
    double b2, parallel;
    adcs_vec3_t parallel_part, perp;
    double vals[3];
    size_t i;
    if ((field == NULL) || (rate == NULL) || (cmd == NULL))
        return ADCS_E_NULL;
    if ((!adcs_is_finite_vec3(field)) || (!adcs_is_finite_vec3(rate)) || (!isfinite(gain)) ||
        (!isfinite(maxdip)) || (gain < 0.0) || (maxdip < 0.0))
        return ADCS_E_RANGE;
    b2 = adcs_vec3_dot(field, field);
    if (b2 <= ADCS_EPS_NORM * ADCS_EPS_NORM) {
        cmd->command = (adcs_vec3_t){0, 0, 0};
        cmd->saturated_axes = 0U;
        return ADCS_E_DEGENERATE;
    }
    parallel = adcs_vec3_dot(rate, field) / b2;
    parallel_part = adcs_vec3_scale(field, parallel);
    perp = adcs_vec3_sub(rate, &parallel_part);
    cmd->command = adcs_vec3_scale(&perp, -gain);
    cmd->saturated_axes = 0U;
    vals[0] = cmd->command.x;
    vals[1] = cmd->command.y;
    vals[2] = cmd->command.z;
    for (i = 0; i < 3; i++)
        if (fabs(vals[i]) > maxdip) {
            vals[i] = copysign(maxdip, vals[i]);
            cmd->saturated_axes |= (uint32_t)(1U << i);
        }
    cmd->command = (adcs_vec3_t){vals[0], vals[1], vals[2]};
    return ADCS_OK;
}
adcs_status_t adcs_wheel_momentum(const adcs_wheel_t *wheels, size_t count, adcs_vec3_t *h) {
    size_t i;
    adcs_vec3_t axis, term;
    if ((wheels == NULL) || (h == NULL))
        return ADCS_E_NULL;
    *h = (adcs_vec3_t){0, 0, 0};
    for (i = 0; i < count; i++) {
        if ((!isfinite(wheels[i].inertia_kg_m2)) || (!isfinite(wheels[i].speed_rad_s)) ||
            (wheels[i].inertia_kg_m2 < 0.0) ||
            adcs_vec3_normalize(&wheels[i].axis_body, ADCS_EPS_NORM, &axis) != ADCS_OK)
            return ADCS_E_RANGE;
        term = adcs_vec3_scale(&axis, wheels[i].inertia_kg_m2 * wheels[i].speed_rad_s);
        *h = adcs_vec3_add(h, &term);
    }
    return ADCS_OK;
}
adcs_status_t adcs_momentum_unload_dipole(const adcs_vec3_t *herr, const adcs_vec3_t *field,
                                          double gain, double maxdip, adcs_actuator_command_t *cmd,
                                          adcs_vec3_t *torque) {
    adcs_vec3_t desired, cross;
    double b2, scale, n;
    if ((herr == NULL) || (field == NULL) || (cmd == NULL) || (torque == NULL))
        return ADCS_E_NULL;
    if ((!adcs_is_finite_vec3(herr)) || (!adcs_is_finite_vec3(field)) || (!isfinite(gain)) ||
        (!isfinite(maxdip)) || (gain < 0.0) || (maxdip < 0.0))
        return ADCS_E_RANGE;
    b2 = adcs_vec3_dot(field, field);
    if (b2 <= ADCS_EPS_NORM * ADCS_EPS_NORM) {
        cmd->command = (adcs_vec3_t){0, 0, 0};
        cmd->saturated_axes = 0U;
        *torque = cmd->command;
        return ADCS_E_DEGENERATE;
    }
    desired = adcs_vec3_scale(herr, -gain);
    cross = adcs_vec3_cross(field, &desired);
    cmd->command = adcs_vec3_scale(&cross, 1.0 / b2);
    n = adcs_vec3_norm(&cmd->command);
    cmd->saturated_axes = 0U;
    if (n > maxdip) {
        scale = maxdip / n;
        cmd->command = adcs_vec3_scale(&cmd->command, scale);
        cmd->saturated_axes = 7U;
    }
    *torque = adcs_vec3_cross(&cmd->command, field);
    return ADCS_OK;
}
adcs_status_t adcs_limit_scalar(double v, const adcs_actuator_limit_t *l, double *o) {
    if ((l == NULL) || (o == NULL))
        return ADCS_E_NULL;
    if ((!isfinite(v)) || (l->min_value > l->max_value))
        return ADCS_E_RANGE;
    *o = ADCS_CLAMP(v, l->min_value, l->max_value);
    return ADCS_OK;
}
typedef enum { GV_OFF=0,GV_NOMINAL=1,GV_DEGRADED=2,GV_FAULT=3 } gv_mode_t;
typedef struct { int enable; const adcs_vec3_t *gyro[3]; } gv_input_t;
typedef struct { double threshold_rad_s; double reentry_threshold_rad_s; uint32_t isolate_confirm; uint32_t reentry_confirm; } gv_config_t;
typedef struct { gv_mode_t mode; uint32_t bad_streak[3]; uint32_t good_streak[3]; int isolated[3]; } gv_state_t;
typedef struct { gv_mode_t mode; adcs_vec3_t voted_rate_rad_s; double distance_rad_s[3]; uint32_t outlier_mask; } gv_output_t;
static gv_input_t gv_input;static gv_config_t gv_config;static gv_state_t gv_state;static gv_output_t gv_output;
void GncRepoGyroVoteStep(void) {

canonical_solution:
adcs_vec3_t median, delta, sum;
double *m = &median.x;
double values[3];
size_t axis, i;
uint32_t count = 0;
uint32_t isolated_count;
gv_output = (gv_output_t){gv_state.mode, {0, 0, 0}, {0, 0, 0}, 0};
if (gv_input.enable == 0) {
    gv_state.mode = GV_OFF;
    gv_state.bad_streak[0] = 0U;
    gv_state.bad_streak[1] = 0U;
    gv_state.bad_streak[2] = 0U;
    gv_state.good_streak[0] = 0U;
    gv_state.good_streak[1] = 0U;
    gv_state.good_streak[2] = 0U;
    gv_state.isolated[0] = 0;
    gv_state.isolated[1] = 0;
    gv_state.isolated[2] = 0;
    gv_output.mode = GV_OFF;
    return;
}
if (gv_state.mode == GV_FAULT) {
    gv_output.mode = GV_FAULT;
    return;
}
if (gv_input.enable != 1 || gv_input.gyro[0] == NULL || gv_input.gyro[1] == NULL ||
    gv_input.gyro[2] == NULL || !adcs_is_finite_vec3(gv_input.gyro[0]) ||
    !adcs_is_finite_vec3(gv_input.gyro[1]) || !adcs_is_finite_vec3(gv_input.gyro[2]) ||
    !isfinite(gv_config.threshold_rad_s) || gv_config.threshold_rad_s < 0 ||
    !isfinite(gv_config.reentry_threshold_rad_s) || gv_config.reentry_threshold_rad_s < 0 ||
    gv_config.reentry_threshold_rad_s > gv_config.threshold_rad_s ||
    gv_config.isolate_confirm < 1U || gv_config.isolate_confirm > 20U ||
    gv_config.reentry_confirm < 1U || gv_config.reentry_confirm > 20U) {
    gv_state.mode = GV_FAULT;
    gv_output.mode = GV_FAULT;
    return;
}
for (axis = 0; axis < 3; axis++) {
    values[0] = ((const double *)gv_input.gyro[0])[axis];
    values[1] = ((const double *)gv_input.gyro[1])[axis];
    values[2] = ((const double *)gv_input.gyro[2])[axis];
    m[axis] = values[0] + values[1] + values[2] - fmin(values[0], fmin(values[1], values[2])) -
              fmax(values[0], fmax(values[1], values[2]));
}
for (i = 0; i < 3; i++) {
    delta = adcs_vec3_sub(gv_input.gyro[i], &median);
    gv_output.distance_rad_s[i] = adcs_vec3_norm(&delta);
    if (gv_output.distance_rad_s[i] > gv_config.threshold_rad_s) {
        gv_output.outlier_mask |= (uint32_t)(1u << i);
        count++;
    }
}
for (i = 0; i < 3; i++) {
    int this_outlier = (gv_output.outlier_mask & (1u << i)) ? 1 : 0;
    if (!gv_state.isolated[i]) {
        if (this_outlier) {
            gv_state.bad_streak[i]++;
            gv_state.good_streak[i] = 0U;
            if (gv_state.bad_streak[i] >= gv_config.isolate_confirm) {
                gv_state.isolated[i] = 1;
                gv_state.good_streak[i] = 0U;
            }
        } else {
            gv_state.bad_streak[i] = 0U;
        }
    } else {
        if (gv_output.distance_rad_s[i] <= gv_config.reentry_threshold_rad_s) {
            gv_state.good_streak[i]++;
            if (gv_state.good_streak[i] >= gv_config.reentry_confirm) {
                gv_state.isolated[i] = 0;
                gv_state.bad_streak[i] = 0U;
                gv_state.good_streak[i] = 0U;
            }
        } else {
            gv_state.good_streak[i] = 0U;
        }
    }
}

isolated_count = (uint32_t)gv_state.isolated[0] + (uint32_t)gv_state.isolated[1] +
                  (uint32_t)gv_state.isolated[2];

if (isolated_count == 0U) {
    if (count == 0) {
        gv_state.mode = GV_NOMINAL;
        gv_output.voted_rate_rad_s = median;
    } else if (count == 1) {
        size_t a = (gv_output.outlier_mask & 1u) ? 1u : 0u,
               b = (gv_output.outlier_mask & 4u) ? 1u : 2u;
        sum = adcs_vec3_add(gv_input.gyro[a], gv_input.gyro[b]);
        gv_output.voted_rate_rad_s = adcs_vec3_scale(&sum, .5);
        gv_state.mode = GV_DEGRADED;
    } else {
        gv_state.mode = GV_FAULT;
        gv_output.voted_rate_rad_s = (adcs_vec3_t){0, 0, 0};
    }
} else if (isolated_count == 1U) {
    size_t p = gv_state.isolated[0] ? 1U : 0U;
    size_t q = gv_state.isolated[2] ? 1U : 2U;
    if (p == 1U && q == 1U) {
        q = 2U;
    }
    delta = adcs_vec3_sub(gv_input.gyro[p], gv_input.gyro[q]);
    if (adcs_vec3_norm(&delta) <= gv_config.threshold_rad_s) {
        sum = adcs_vec3_add(gv_input.gyro[p], gv_input.gyro[q]);
        gv_output.voted_rate_rad_s = adcs_vec3_scale(&sum, .5);
        gv_state.mode = GV_DEGRADED;
    } else {
        gv_state.mode = GV_FAULT;
        gv_output.voted_rate_rad_s = (adcs_vec3_t){0, 0, 0};
    }
} else {
    gv_state.mode = GV_FAULT;
    gv_output.voted_rate_rad_s = (adcs_vec3_t){0, 0, 0};
}
gv_output.mode = gv_state.mode;
return;

test:
}
#include <assert.h>
int main(void){adcs_vec3_t a={1,2,3},b={1.2,1.8,3.1},c={.9,2.1,2.8},far={9,9,9},far2={-9,-9,-9},nanv={NAN,0,0};
 gv_config.threshold_rad_s=.5;gv_config.reentry_threshold_rad_s=.5;gv_config.isolate_confirm=3;gv_config.reentry_confirm=3;gv_state=(gv_state_t){GV_OFF,{0,0,0},{0,0,0},{0,0,0}};gv_input=(gv_input_t){1,{&a,&b,&c}};GncRepoGyroVoteStep();
 assert(gv_output.mode==GV_NOMINAL);assert(fabs(gv_output.voted_rate_rad_s.x-1)<1e-14&&fabs(gv_output.voted_rate_rad_s.y-2)<1e-14&&fabs(gv_output.voted_rate_rad_s.z-3)<1e-14);assert(gv_output.outlier_mask==0);assert(fabs(gv_output.distance_rad_s[0])<2e-15);assert(fabs(gv_output.distance_rad_s[1]-.3)<1e-14);assert(fabs(gv_output.distance_rad_s[2]-sqrt(.06))<1e-14);
 gv_input.gyro[2]=&far;GncRepoGyroVoteStep();assert(gv_output.mode==GV_DEGRADED);assert(fabs(gv_output.voted_rate_rad_s.x-1.1)<1e-14&&fabs(gv_output.voted_rate_rad_s.y-1.9)<1e-14);assert(gv_output.outlier_mask==4u);
 gv_input.gyro[1]=&far2;GncRepoGyroVoteStep();assert(gv_output.mode==GV_FAULT);assert(adcs_vec3_norm(&gv_output.voted_rate_rad_s)==0);gv_input=(gv_input_t){1,{&a,&b,&c}};GncRepoGyroVoteStep();assert(gv_output.mode==GV_FAULT);
 gv_input.enable=0;GncRepoGyroVoteStep();assert(gv_output.mode==GV_OFF);
 gv_input=(gv_input_t){1,{NULL,&b,&c}};GncRepoGyroVoteStep();assert(gv_output.mode==GV_FAULT);
 gv_input.enable=0;GncRepoGyroVoteStep();gv_input=(gv_input_t){1,{&a,&nanv,&c}};GncRepoGyroVoteStep();assert(gv_output.mode==GV_FAULT);
 gv_input.enable=0;GncRepoGyroVoteStep();gv_input=(gv_input_t){1,{&a,&b,&c}};gv_config.threshold_rad_s=-1;GncRepoGyroVoteStep();assert(gv_output.mode==GV_FAULT);
 gv_input.enable=0;GncRepoGyroVoteStep();gv_config.threshold_rad_s=0;gv_config.reentry_threshold_rad_s=0;gv_input=(gv_input_t){1,{&a,&a,&a}};GncRepoGyroVoteStep();assert(gv_output.mode==GV_NOMINAL&&gv_output.outlier_mask==0);{assert(fabs(gv_output.distance_rad_s[0])<1e-15);assert(fabs(gv_output.distance_rad_s[1])<1e-15);assert(fabs(gv_output.distance_rad_s[2])<1e-15);}

    /* persistent isolation: sensor 2 drifts for isolate_confirm cycles and gets isolated.
       While isolated, even a cycle where sensor 2 looks quiet must still vote using only the
       two trusted sensors (DEGRADED), not fold sensor 2 back into a NOMINAL median. */
    gv_input.enable=0;GncRepoGyroVoteStep();
    gv_config.threshold_rad_s=.5;gv_config.reentry_threshold_rad_s=.3;gv_config.isolate_confirm=2;gv_config.reentry_confirm=2;
    gv_state=(gv_state_t){GV_OFF,{0,0,0},{0,0,0},{0,0,0}};
    gv_input=(gv_input_t){1,{&a,&b,&far}};
    GncRepoGyroVoteStep();
    assert(gv_output.mode==GV_DEGRADED);
    assert(gv_state.isolated[2]==0);
    GncRepoGyroVoteStep();
    assert(gv_output.mode==GV_DEGRADED);
    assert(gv_state.isolated[2]==1);
    gv_input.gyro[2]=&c;
    GncRepoGyroVoteStep();
    assert(gv_output.mode==GV_DEGRADED);
    assert(gv_state.isolated[2]==1);
    assert(fabs(gv_output.voted_rate_rad_s.x-1.1)<1e-14&&fabs(gv_output.voted_rate_rad_s.y-1.9)<1e-14);

    /* a second consecutive near-agreement reaches reentry_confirm and reinstates sensor 2,
       so the same steady input now yields NOMINAL with the true 3-sensor median */
    GncRepoGyroVoteStep();
    assert(gv_output.mode==GV_NOMINAL);
    assert(gv_state.isolated[2]==0);

    /* disabling clears isolation and streak state entirely, not just mode */
