    qs_state = (qs_state_t){QS_HOLD, 0U, 0.0, 0, {0.0, 0.0, 0.0}};
    qs_output.mode = QS_HOLD;
    return;
}
if (qs_state.mode == QS_FAULT) {
    qs_output.mode = QS_FAULT;
    return;
}

config_ok = (qs_input.enable == 1) && (qs_input.current_q_bi != NULL) &&
            (qs_input.target_q_bi != NULL) &&
            isfinite(qs_config.max_rate_rad_cycle) &&
            (qs_config.max_rate_rad_cycle > 0.0) &&
            (qs_config.max_rate_rad_cycle <= ADCS_PI) &&
            isfinite(qs_config.max_accel_rad_cycle2) &&
            (qs_config.max_accel_rad_cycle2 > 0.0) &&
            isfinite(qs_config.settle_angle_rad) &&
            (qs_config.settle_angle_rad >= 0.0) &&
            (qs_config.settle_angle_rad <= qs_config.max_rate_rad_cycle) &&
            isfinite(qs_config.settle_rate_rad_cycle) &&
            (qs_config.settle_rate_rad_cycle >= 0.0) &&
            (qs_config.settle_rate_rad_cycle <= qs_config.max_rate_rad_cycle) &&
            (qs_config.settle_cycles >= 1U) && (qs_config.settle_cycles <= 20U) &&
            (adcs_quat_normalize(qs_input.current_q_bi, &current) == ADCS_OK) &&
            (adcs_quat_normalize(qs_input.target_q_bi, &target) == ADCS_OK);
