    qs_state = (qs_state_t){QS_FAULT, 0U, 0.0, 0, {0.0, 0.0, 0.0}};
    qs_output.mode = QS_FAULT;
    return;
}

conjugate = adcs_quat_conjugate(&current);
relative = adcs_quat_multiply(&target, &conjugate);
