    relative = (adcs_quat_t){-relative.w, -relative.x, -relative.y, -relative.z};
}
vector = (adcs_vec3_t){relative.x, relative.y, relative.z};
sine_half = adcs_vec3_norm(&vector);
angle = 2.0 * atan2(sine_half, relative.w);
if (sine_half > ADCS_EPS_NORM) {
    if (adcs_vec3_normalize(&vector, ADCS_EPS_NORM, &axis) != ADCS_OK) {
        qs_state = (qs_state_t){QS_FAULT, 0U, 0.0, 0, {0.0, 0.0, 0.0}};
        qs_output.mode = QS_FAULT;
        return;
    }
    if ((qs_state.axis_valid != 0) &&
        (adcs_vec3_dot(&axis, &qs_state.previous_axis) < 0.0)) {
        qs_state.commanded_rate_rad_cycle = 0.0;
        qs_output.reversal_reset = 1;
    }
    qs_state.previous_axis = axis;
    qs_state.axis_valid = 1;
} else {
    /* At zero angle there is no new axis and the previous axis is retained. */
}

braking_rate = sqrt(2.0 * qs_config.max_accel_rad_cycle2 * angle);
desired_rate = (braking_rate < qs_config.max_rate_rad_cycle)
                   ? braking_rate
                   : qs_config.max_rate_rad_cycle;
previous_rate = qs_state.commanded_rate_rad_cycle;
delta_rate = desired_rate - previous_rate;
if (delta_rate > qs_config.max_accel_rad_cycle2) {
    delta_rate = qs_config.max_accel_rad_cycle2;
} else if (delta_rate < -qs_config.max_accel_rad_cycle2) {
    delta_rate = -qs_config.max_accel_rad_cycle2;
} else {
    /* The desired profile rate is reachable this cycle. */
}
qs_state.commanded_rate_rad_cycle = previous_rate + delta_rate;
step = (qs_state.commanded_rate_rad_cycle < angle)
           ? qs_state.commanded_rate_rad_cycle
           : angle;

if ((angle <= qs_config.settle_angle_rad) &&
    (qs_state.commanded_rate_rad_cycle <= qs_config.settle_rate_rad_cycle)) {
    if (qs_state.mode != QS_SETTLE) {
        qs_state.settled = 0U;
    }
    qs_state.mode = QS_SETTLE;
    qs_state.settled++;
    if (qs_state.settled >= qs_config.settle_cycles) {
        qs_state.mode = QS_HOLD;
        qs_state.commanded_rate_rad_cycle = 0.0;
    } else {
        /* More joint angle and rate settling evidence is required. */
    }
} else {
    qs_state.settled = 0U;
    if (qs_state.commanded_rate_rad_cycle > previous_rate) {
        qs_state.mode = QS_ACCEL;
    } else if (qs_state.commanded_rate_rad_cycle >=
               qs_config.max_rate_rad_cycle) {
        qs_state.mode = QS_CRUISE;
    } else {
        qs_state.mode = QS_DECEL;
    }
}

if (step < angle) {
    half = 0.5 * step;
    vector = adcs_vec3_scale(&axis, sin(half));
    increment = (adcs_quat_t){cos(half), vector.x, vector.y, vector.z};
    qs_output.command_q_bi = adcs_quat_multiply(&increment, &current);
    if (adcs_quat_normalize(&qs_output.command_q_bi,
                            &qs_output.command_q_bi) != ADCS_OK) {
        qs_state = (qs_state_t){QS_FAULT, 0U, 0.0, 0, {0.0, 0.0, 0.0}};
        qs_output.mode = QS_FAULT;
        qs_output.command_q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
        return;
    }
} else {
    qs_output.command_q_bi = target;
}
qs_output.mode = qs_state.mode;
qs_output.settled = qs_state.settled;
qs_output.error_angle_rad = angle;
qs_output.applied_step_rad = step;
qs_output.commanded_rate_rad_cycle = qs_state.commanded_rate_rad_cycle;
qs_output.braking_rate_rad_cycle = braking_rate;
qs_output.slew_axis = axis;
return;

