            (wo_input.count == 4U) && isfinite(wo_config.release_rad_s) &&
            (wo_config.release_rad_s >= 0.0) && isfinite(wo_config.warn_rad_s) &&
            (wo_config.warn_rad_s > wo_config.release_rad_s) &&
            isfinite(wo_config.trip_rad_s) &&
            (wo_config.trip_rad_s > wo_config.warn_rad_s) &&
            isfinite(wo_config.dt_s) && (wo_config.dt_s > 0.0) &&
            isfinite(wo_config.prediction_horizon_s) &&
            (wo_config.prediction_horizon_s > 0.0) &&
            isfinite(wo_config.gain) && (wo_config.gain >= 0.0) &&
            isfinite(wo_config.torque_limit) &&
            (wo_config.torque_limit > 0.0) &&
            isfinite(wo_config.torque_slew) && (wo_config.torque_slew > 0.0) &&
            (wo_config.minimum_active_cycles >= 1U) &&
            (wo_config.minimum_active_cycles <= 100U) &&
            (wo_config.release_cycles >= 1U) &&
            (wo_config.release_cycles <= 100U) &&
