                wo_state.clean = 0U;
                wo_state.recovery_count = 0U;
            } else {
                /* More release evidence is required. */
            }
        } else {
            wo_state.clean = 0U;
        }
    } else {
        /* Minimum active residence has not elapsed. */
    }
} else if (wo_state.mode == WO_RECOVERY) {
    if (predicted_maximum >= wo_config.trip_rad_s) {
        wo_state.mode = WO_ACTIVE;
        wo_state.elapsed = 0U;
        wo_state.recovery_count = 0U;
    } else {
        wo_state.recovery_count++;
        if (wo_state.recovery_count >= wo_config.recovery_cycles) {
            wo_state.mode = WO_OFF;
            wo_state.recovery_count = 0U;
        } else {
            /* Continue ramping down during recovery. */
        }
    }
} else {
    /* All valid nonfault modes are handled above. */
}
if (wo_state.mode == WO_ACTIVE) {
    desired = adcs_vec3_scale(&momentum, -wo_config.gain);
}
raw[0] = desired.x;
raw[1] = desired.y;
raw[2] = desired.z;
output_axis = &wo_output.torque.x;
magnitude_limit = (adcs_actuator_limit_t){
